import{_ as t,o as s,c as r,ah as n}from"./chunks/framework.C-FRNfAJ.js";const g=JSON.parse('{"title":"Résultats et certification","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/coordinateur/resultats.md","filePath":"src/guide/coordinateur/resultats.md"}'),a={name:"guide/coordinateur/resultats.md"};function o(i,e,l,u,c,d){return s(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="resultats-et-certification" tabindex="-1">Résultats et certification <a class="header-anchor" href="#resultats-et-certification" aria-label="Permalink to &quot;Résultats et certification&quot;">​</a></h1><p>Depuis la fiche d&#39;une cohorte, <strong>Présence</strong> et <strong>Résultats</strong> donnent le suivi des apprenants. Vous y saisissez les décisions du jury, produisez le procès-verbal et délivrez les certificats.</p><h2 id="suivre-la-presence-et-les-notes" tabindex="-1">Suivre la présence et les notes <a class="header-anchor" href="#suivre-la-presence-et-les-notes" aria-label="Permalink to &quot;Suivre la présence et les notes&quot;">​</a></h2><p>Les pages sont les mêmes que celles du Formateur Principal : voir <a href="./../equipe/formateur.html#la-presence">Formateur Principal</a>. En complément, vous pouvez <strong>saisir et corriger la présence en présentiel</strong> à la place du formateur, et <strong>ouvrir des rattrapages</strong>.</p><p>Rappel : tant que l&#39;<strong>identifiant du cours Sève</strong> n&#39;est pas renseigné sur la cohorte, ni les classes virtuelles ni les notes ne remontent. La page vous le signale.</p><h2 id="les-decisions-du-jury" tabindex="-1">Les décisions du jury <a class="header-anchor" href="#les-decisions-du-jury" aria-label="Permalink to &quot;Les décisions du jury&quot;">​</a></h2><p>Seul vous (et l&#39;Administrateur) saisissez le jury, <strong>à partir du démarrage de la cohorte</strong>. Sur la page <strong>Résultats</strong>, cliquez sur l&#39;apprenant puis <strong>Saisir les décisions</strong>. Chaque décision reste <strong>en attente</strong> tant que le jury ne l&#39;a pas prise ; les notes sont facultatives et <strong>ne comptent pas dans la moyenne</strong>.</p><table tabindex="0"><thead><tr><th>Décision</th><th>Ce que vous saisissez</th></tr></thead><tbody><tr><td><strong>Projet tutoré</strong></td><td>Sujet, validé ou non, note sur 20</td></tr><tr><td><strong>Soutenance</strong></td><td>Date, validée ou non, note sur 20</td></tr><tr><td><strong>Stage</strong></td><td>Entreprise d&#39;accueil (reprise de la convention de stage s&#39;il y en a une), validé ou non</td></tr></tbody></table><p>La <strong>soutenance</strong> validée est l&#39;une des conditions du certificat. Le <strong>stage</strong> ne bloque jamais le certificat.</p><h3 id="le-president-du-jury" tabindex="-1">Le président du jury <a class="header-anchor" href="#le-president-du-jury" aria-label="Permalink to &quot;Le président du jury&quot;">​</a></h3><p>Indiquez le <strong>président du jury</strong> avec les décisions : c&#39;est lui qui signe le certificat, et son nom y est imprimé. <strong>Sans président, le certificat ne peut pas être délivré.</strong></p><h3 id="les-membres-du-jury" tabindex="-1">Les membres du jury <a class="header-anchor" href="#les-membres-du-jury" aria-label="Permalink to &quot;Les membres du jury&quot;">​</a></h3><p>Dans <strong>Membres du jury</strong>, ajoutez pour chaque <strong>date de soutenance</strong> les jurés présents : nom et adresse e-mail, sans compte Kura. Chacun reçoit un <strong>jeton</strong>, dû une fois les soutenances tenues. Voir <a href="./remunerations.html">Rémunérations et commissions</a>.</p><h2 id="le-proces-verbal-de-soutenance" tabindex="-1">Le procès-verbal de soutenance <a class="header-anchor" href="#le-proces-verbal-de-soutenance" aria-label="Permalink to &quot;Le procès-verbal de soutenance&quot;">​</a></h2><p>Quand le jury a <strong>statué sur la soutenance de chaque apprenant confirmé</strong> de la cohorte, le panneau <strong>Documents</strong> de la fiche propose <strong>Générer le PV</strong>. Le procès-verbal est <strong>numéroté</strong> (<code>PVS-NB-AAAA-XXX</code>), <strong>scellé</strong> et conservé.</p><p>Il n&#39;est <strong>jamais régénéré à la consultation</strong>. Si les décisions du jury sont corrigées ensuite, la fiche vous propose d&#39;en générer un nouveau : il <strong>remplace</strong> l&#39;ancien, qui reste téléchargeable, marqué « remplacé ». Tant qu&#39;une soutenance reste sans décision, aucun PV n&#39;est produit.</p><h2 id="delivrer-le-certificat" tabindex="-1">Délivrer le certificat <a class="header-anchor" href="#delivrer-le-certificat" aria-label="Permalink to &quot;Délivrer le certificat&quot;">​</a></h2><p>Sur la page de résultats, le bloc <strong>Certification</strong> montre les quatre conditions de chaque apprenant, remplies ou non :</p><ol><li>tous les blocs notés, <strong>moyenne ≥ 10/20</strong> ;</li><li><strong>aucun bloc sous 8/20</strong> ;</li><li><strong>soutenance validée</strong> par le jury ;</li><li><strong>solde des frais de formation réglé</strong>.</li></ol><p>Aucune condition n&#39;en compense une autre. Quand les quatre sont réunies et que le président du jury est saisi, <strong>Délivrer le certificat</strong> est disponible, <strong>une seule fois</strong> par apprenant.</p><p>La délivrance :</p><ul><li>fige un <strong>PDF scellé</strong> (<code>CERT-NB-AAAA-XXX</code>) avec la <strong>mention</strong> (Passable dès 10/20 ; Assez bien, Bien et Très bien aux seuils que règle l&#39;Administrateur, 12, 14 et 16 par défaut), et le <strong>relevé de compétences</strong> (<code>REL-NB-AAAA-XXX</code>), envoyés à l&#39;apprenant par e-mail ;</li><li><strong>termine l&#39;inscription</strong> ;</li><li>retire l&#39;apprenant du cours de sa cohorte dans Sève ;</li><li>fait passer son compte à l&#39;état <strong>Canopé</strong> et l&#39;inscrit au <strong>Parcours Canopé</strong>.</li></ul><p>Si le cours Sève du Parcours Canopé n&#39;est pas encore renseigné, l&#39;inscription Canopé <strong>attend</strong> qu&#39;il le soit.</p><h2 id="l-attestation-partielle" tabindex="-1">L&#39;attestation partielle <a class="header-anchor" href="#l-attestation-partielle" aria-label="Permalink to &quot;L&#39;attestation partielle&quot;">​</a></h2><p>Pour une inscription <strong>abandonnée</strong> (volontaire ou pour impayé) avec <strong>au moins un bloc validé</strong>, <strong>Délivrer l&#39;attestation partielle</strong> produit une attestation qui reprend les blocs validés, ceux qui ne l&#39;ont pas été ou n&#39;ont pas été suivis, et le motif de l&#39;interruption, avec le relevé de compétences. Il n&#39;y a <strong>jamais de certificat partiel</strong>. S&#39;il n&#39;y a aucun bloc validé, il n&#39;y a rien à attester.</p>',25)])])}const m=t(a,[["render",o]]);export{g as __pageData,m as default};
